            ["tr.Silent.name"] = new[] { "Not a sound", "Ни звука", "Үнсіз", "Ni un ruido", "Nem um som" },
            ["tr.Silent.desc"] = new[] { "Banish an entity without being heard once.", "Изгони сущность, ни разу не выдав себя шумом.", "Шуыңмен бір рет те білдірмей тылсым күшті қу.", "Expulsa una entidad sin que te oiga ni una vez.", "Expulse uma entidade sem ser ouvido nenhuma vez." },
