                "{0} / {1} XP hasta la próxima entidad",
                "{0} / {1} XP até a próxima entidade" },
            ["journal_count"] = new[] { "Known: {0} of {1}", "Известно: {0} из {1}", "Белгілі: {0} / {1}", "Conocidas: {0} de {1}", "Conhecidas: {0} de {1}" },
            ["practice"] = new[] { "TRY", "УЧИТЬ", "ҮЙРЕНУ", "PROBAR", "TREINAR" },
            ["learned"] = new[] { "✓ LEARNED", "✓ ИЗУЧЕНО", "✓ ҮЙРЕНДІҢ", "✓ APRENDIDO", "✓ APRENDIDO" },
            ["learned_count"] = new[] { "Gestures learned: {0} of {1}", "Жестов изучено: {0} из {1}", "Үйренген қимылдар: {0} / {1}", "Gestos aprendidos: {0} de {1}", "Gestos aprendidos: {0} de {1}" },
            ["practice_title"] = new[] { "PRACTICE: {0}", "ТРЕНИРОВКА: {0}", "ЖАТТЫҒУ: {0}", "PRÁCTICA: {0}", "TREINO: {0}" },
            ["practice_try"] = new[] {
                "Do the gesture anywhere on the screen.",
                "Сделай жест в любом месте экрана.",
                "Қимылды экранның кез келген жерінде жаса.",
