                "Aprendido! {0}: pronto para a noite." },
            ["h.Practice"] = new[] {
                "Not every gesture is learned yet. Practise them in the Journal → Items: there is no time to learn in the dark.",
                "Не все жесты изучены. Потренируйся в Дневнике → Предметы: в темноте учиться некогда.",
                "Барлық қимыл үйренілген жоқ. Күнделік → Заттар бөлімінде жаттық: қараңғыда үйренуге уақыт жоқ.",
                "Aún no has aprendido todos los gestos. Practícalos en Diario → Objetos: en la oscuridad no hay tiempo para aprender.",
                "Nem todos os gestos foram aprendidos. Treine no Diário → Itens: no escuro não dá tempo de aprender." },
            // ---------- улики ----------
            ["c.Frost.name"] = new[] { "Cold", "Холод", "Суық", "Frío", "Frio" },
            ["c.Frost.howto"] = new[] { "In the thermal camera the lair shows as a blue cold spot, below zero.", "В тепловизоре логово видно синим холодным пятном, ниже нуля.", "Тепловизорда ұя көк суық дақ болып көрінеді, нөлден төмен.", "En la cámara térmica la guarida aparece como una mancha fría azul, bajo cero.", "Na câmera térmica o covil aparece como uma mancha fria azul, abaixo de zero." },
            ["c.Whisper.name"] = new[] { "Whisper", "Шёпот", "Сыбыр", "Susurro", "Sussurro" },
            ["c.Whisper.howto"] = new[] { "A quiet whisper from one spot. With headphones you can tell where.", "Тихий шёпот из одной точки. В наушниках слышно, откуда.", "Бір нүктеден шыққан ақырын сыбыр. Құлаққаппен қайдан екені естіледі.", "Un susurro desde un punto. Con auriculares se oye de dónde.", "Um sussurro vindo de um ponto. Com fones dá para ouvir de onde." },
            ["c.Compass.name"] = new[] { "EMF 5", "ЭМП 5", "ЭМӨ 5", "EMF 5", "EMF 5" },
            ["c.Compass.howto"] = new[] { "The EMF reader hits 5 when aimed at the lair.", "ЭМП-детектор показывает 5, когда наведён на логово.", "ЭМӨ-детектор ұяға бағытталғанда 5 көрсетеді.", "El detector EMF marca 5 al apuntar a la guarida.", "O detector EMF marca 5 quando apontado para o covil." },
            ["c.Static.name"] = new[] { "Static", "Помехи", "Кедергі", "Interferencias", "Chiado" },
            ["c.Static.howto"] = new[] { "The picture tears with static when the camera points at the lair.", "Картинка рвётся помехами, когда камера направлена на логово.", "Камера ұяға бағытталғанда сурет кедергімен бұзылады.", "La imagen se rompe con interferencias al apuntar a la guarida.", "A imagem se rasga com chiado ao apontar para o covil." },
            ["c.Knock.name"] = new[] { "Knocking", "Стук", "Тықыл", "Golpes", "Batidas" },
            ["c.Knock.howto"] = new[] { "Three knocks from one place. Floor creaks are not a clue.", "Три удара из одного места. Скрипы пола — не улика.", "Бір жерден үш рет тықыл. Еденнің сықыры — дәлел емес.", "Tres golpes desde un sitio. Los crujidos del suelo no son pista.", "Três batidas de um lugar. Rangidos no chão não são pista." },
            ["c.Radio.name"] = new[] { "Radio", "Радио", "Радио", "Radio", "Rádio" },
            ["c.Radio.howto"] = new[] { "Turn on the spirit box and ask out loud: “Are you here?” — it answers in a distorted voice.", "Включи радио духов и спроси вслух: «Ты здесь?» — оно ответит искажённым голосом.", "Рухтар радиосын қосып, дауыстап сұра: «Сен мұндасың ба?» — ол бұрмаланған дауыспен жауап береді.", "Enciende la radio de espíritus y pregunta en voz alta: «¿Estás aquí?»: responde con voz distorsionada.", "Ligue o rádio dos espíritos e pergunte em voz alta: “Você está aí?” — ele responde com voz distorcida." },
            ["c.NightVision.name"] = new[] { "Silhouette", "Силуэт", "Сұлба", "Silueta", "Silhueta" },
            ["c.NightVision.howto"] = new[] { "Through the night camera a silhouette flashes in the lair for a moment.", "В ночной камере на миг виден силуэт в логове.", "Түнгі камерада ұяда бір сәтке сұлба көрінеді.", "Con la cámara nocturna se ve un instante una silueta en la guarida.", "Na câmera noturna uma silhueta aparece por um instante no covil." },
        };
    }
}
